begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_catalog;
select plan(10);
insert into auth.users(id,email) values('11111111-1111-4111-8111-111111111111','coach-understanding@example.com') on conflict do nothing;
insert into public.profiles(id,username,timezone) values('11111111-1111-4111-8111-111111111111','coach_understanding','UTC') on conflict(id) do nothing;
insert into public.coach_topics(id,owner_id,title) values('22222222-2222-4222-8222-222222222222','11111111-1111-4111-8111-111111111111','Writing');
insert into public.coach_threads(id,owner_id,topic_id,title) values('33333333-3333-4333-8333-333333333333','11111111-1111-4111-8111-111111111111','22222222-2222-4222-8222-222222222222','Morning work');
insert into public.coach_messages(id,owner_id,thread_id,sequence,role,content) values('44444444-4444-4444-8444-444444444444','11111111-1111-4111-8111-111111111111','33333333-3333-4333-8333-333333333333',1,'user','I prefer mornings');
insert into public.coach_memories(id,owner_id,topic_id,content,source_message_id) values('55555555-5555-4555-8555-555555555555','11111111-1111-4111-8111-111111111111','22222222-2222-4222-8222-222222222222','I prefer mornings','44444444-4444-4444-8444-444444444444');
select ok(public.save_coach_summary('11111111-1111-4111-8111-111111111111','22222222-2222-4222-8222-222222222222',1,'Morning preference',array['44444444-4444-4444-8444-444444444444'::uuid]),'sourced summary saved');
select ok(not public.save_coach_summary('11111111-1111-4111-8111-111111111111','22222222-2222-4222-8222-222222222222',0,'Late summary','{}'),'late summary cannot overwrite newer understanding');
update public.coach_memories set content='I prefer evenings',source_message_id=null where id='55555555-5555-4555-8555-555555555555';
select is((select content from public.coach_memories where id='55555555-5555-4555-8555-555555555555'),'I prefer evenings','memory edit persists');
select is((select summary from public.coach_topics where id='22222222-2222-4222-8222-222222222222'),'','memory edit invalidates derived summary');
select ok(exists(select 1 from public.coach_forgotten_sources where message_id='44444444-4444-4444-8444-444444444444'),'old preference source excluded from future extraction');
select ok(not public.save_coach_summary('11111111-1111-4111-8111-111111111111','22222222-2222-4222-8222-222222222222',2,'Mornings again',array['44444444-4444-4444-8444-444444444444'::uuid]),'suppressed source cannot revive old summary');
insert into public.coach_memories(owner_id,topic_id,content,source_message_id) values('11111111-1111-4111-8111-111111111111','22222222-2222-4222-8222-222222222222','A sourced preference','44444444-4444-4444-8444-444444444444');
select lives_ok($$delete from public.coach_threads where id='33333333-3333-4333-8333-333333333333'$$,'thread deletion safely detaches optional memory sources');
select is((select count(*)::integer from public.coach_memories where owner_id='11111111-1111-4111-8111-111111111111'),2,'confirmed preferences survive deleting their transcript');
select ok(not exists(select 1 from public.coach_memories where source_message_id is not null),'removed transcripts leave no dangling memory sources');
select ok(not public.save_coach_summary('11111111-1111-4111-8111-111111111111','22222222-2222-4222-8222-222222222222',1,'Late summary','{}'),'new preferences and deletions fence older summaries');
select * from finish();rollback;
